catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;

    if (!newValue) {
        // Default: show amount, hide leave_days
        g_form.setDisplay('amount', true);
        g_form.setDisplay('leave_days', false);
        return;
    }

    // Look up the reward_type choice value from the referenced reward catalog record
    g_form.getReference('reward_type', function (ref) {
        if (!ref) return;

        var rewardType = ref.reward_type + '';

        if (rewardType === 'extra_leave_credit') {
            g_form.setDisplay('amount', false);
            g_form.setDisplay('leave_days', true);
            g_form.clearValue('amount');
        } else if (rewardType === 'team_recognition_award') {
            g_form.setDisplay('amount', true);
            g_form.setDisplay('leave_days', false);
            g_form.clearValue('leave_days');
        } else {
            // Default for spot_bonus, voucher, etc.
            g_form.setDisplay('amount', true);
            g_form.setDisplay('leave_days', false);
            g_form.clearValue('leave_days');
        }
    });
}
